import { createServer } from 'node:http';
import { appendFile, readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { classifyReportAudiences, classifyStakeholderResponse, draftStakeholderEmail, outcomeToStatus, researchMarketIntelligence, synthesizeRequirements } from './src/openai.mjs';
import { DECISION_EVENT_TYPES, isRecordedDecision } from './src/decision-memory.mjs';

const root = new URL('.', import.meta.url).pathname.replace(/^\/(.:)/, '$1');
const port = Number(process.env.PORT || 4173);
const apiVersion = 'pm-api-5';
const decisionEventsPath = join(root, 'data', 'decision-events.ndjson');
const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg':'image/svg+xml', '.png':'image/png', '.jpg':'image/jpeg', '.jpeg':'image/jpeg', '.webp':'image/webp' };

const sendJson = (res, status, value) => { res.writeHead(status, { 'Content-Type':'application/json; charset=utf-8', 'Cache-Control':'no-store' }); res.end(JSON.stringify(value)); };
const readJson = req => new Promise((resolve, reject) => {
  let body='';
  req.on('data', chunk => { body += chunk; if (body.length > 100_000) reject(new Error('Request is too large.')); });
  req.on('end', () => { try { resolve(JSON.parse(body || '{}')); } catch { reject(new Error('Invalid JSON request.')); } });
  req.on('error', reject);
});

createServer(async (req, res) => {
  const pathname = new URL(req.url, 'http://localhost').pathname;
  if (pathname === '/api/health' && req.method === 'GET') {
    sendJson(res, 200, { ok:true, apiVersion, openaiConfigured:Boolean(process.env.OPENAI_API_KEY), model:process.env.OPENAI_MODEL || 'gpt-4o-mini' });
    return;
  }
  if (pathname === '/api/openai-status' && req.method === 'GET') {
    sendJson(res, 200, { configured: Boolean(process.env.OPENAI_API_KEY), model: process.env.OPENAI_MODEL || 'gpt-4o-mini' });
    return;
  }
  if (pathname === '/api/decision-events' && req.method === 'GET') {
    try {
      const lines=(await readFile(decisionEventsPath,'utf8')).split(/\r?\n/).filter(Boolean);
      sendJson(res,200,{events:lines.map(line=>JSON.parse(line)).filter(isRecordedDecision)});
    } catch (error) {
      if(error.code==='ENOENT')sendJson(res,200,{events:[]});else sendJson(res,500,{error:'Decision memory could not be read.'});
    }
    return;
  }
  if (pathname === '/api/decision-events' && req.method === 'POST') {
    try {
      const event=await readJson(req);
      if(!event.id||!event.type||!event.title||!event.at)throw new Error('Decision event is incomplete.');
      if(!DECISION_EVENT_TYPES.has(event.type))throw new Error('Decision Memory only accepts requirement approvals and rejections.');
      if(!String(event.data?.rationale||'').trim())throw new Error('An approval or rejection reason is required.');
      const immutableEvent={id:String(event.id),type:String(event.type),title:String(event.title),description:String(event.description||''),actor:String(event.actor||'PM'),data:event.data||{},at:String(event.at),provenance:'Append-only application event'};
      await appendFile(decisionEventsPath,`${JSON.stringify(immutableEvent)}\n`,'utf8');
      sendJson(res,201,{ok:true,id:immutableEvent.id});
    } catch(error){sendJson(res,400,{error:error.message})}
    return;
  }
  if (pathname === '/api/interpret-stakeholder' && req.method === 'POST') {
    try {
      const input = await readJson(req);
      const interpretation = await classifyStakeholderResponse(input);
      sendJson(res, 200, { ...interpretation, status: outcomeToStatus(interpretation.outcome), requiresConfirmation: true });
    } catch (error) {
      const configurationError = /OPENAI_API_KEY/.test(error.message);
      sendJson(res, configurationError ? 503 : 502, { error: error.message });
    }
    return;
  }
  if (pathname === '/api/draft-email' && req.method === 'POST') {
    try {
      sendJson(res, 200, await draftStakeholderEmail(await readJson(req)));
    } catch (error) {
      sendJson(res, /OPENAI_API_KEY/.test(error.message) ? 503 : 502, { error:error.message });
    }
    return;
  }
  if (pathname === '/api/synthesize-requirements' && req.method === 'POST') {
    try {
      sendJson(res, 200, await synthesizeRequirements(await readJson(req)));
    } catch (error) {
      sendJson(res, /OPENAI_API_KEY/.test(error.message) ? 503 : 502, { error:error.message });
    }
    return;
  }
  if (pathname === '/api/classify-report-audiences' && req.method === 'POST') {
    try {
      sendJson(res, 200, await classifyReportAudiences(await readJson(req)));
    } catch (error) {
      sendJson(res, /OPENAI_API_KEY/.test(error.message) ? 503 : 502, { error:error.message });
    }
    return;
  }
  if (pathname === '/api/market-intelligence' && req.method === 'POST') {
    try {
      sendJson(res, 200, await researchMarketIntelligence(await readJson(req)));
    } catch (error) {
      sendJson(res, /OPENAI_API_KEY/.test(error.message) ? 503 : 502, { error:error.message });
    }
    return;
  }
  if (pathname.startsWith('/sources/')) {
    const sourceTarget=decodeURIComponent(pathname.slice('/sources/'.length));
    if (/^https?:\/\//i.test(sourceTarget)) { res.writeHead(302, { Location:sourceTarget, 'Cache-Control':'no-store' }).end(); return; }
  }
  const decodedPathname=decodeURIComponent(pathname);
  const requested = decodedPathname === '/' ? '/public/index.html' : decodedPathname.startsWith('/sources/') ? `/data${decodedPathname}` : (decodedPathname.startsWith('/data/') || decodedPathname.startsWith('/src/')) ? decodedPathname : `/public${decodedPathname}`;
  const path = normalize(join(root, requested));
  if (!path.startsWith(normalize(root))) { res.writeHead(403).end('Forbidden'); return; }
  try {
    const body = await readFile(path);
    res.writeHead(200, { 'Content-Type': types[extname(path)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
    res.end(body);
  } catch {
    res.writeHead(404).end('Not found');
  }
}).listen(port, () => console.log(`PM (${apiVersion}): http://localhost:${port}`));
export function buildModel(records,config,statuses={},context={},overrides={}) {
  const relevant=records.filter(r=>r.vehicle===config.vehicle&&r.market===config.market&&r.quality!=='low'&&r.feature&&!INVALID_FEATURE.test(r.feature));
  const byFeature=new Map();
  for(const record of relevant){if(!byFeature.has(record.feature))byFeature.set(record.feature,{feedback:[],studies:[],external:[],competitors:[]});byFeature.get(record.feature).feedback.push(record)}
  const intelligence=marketInputs(context,config,[...byFeature.keys()]);
  for(const [feature,studies] of intelligence.assigned)byFeature.get(feature).studies.push(...studies);
  for(const study of intelligence.unmatched){const feature=String(study.cells.A).trim();if(!byFeature.has(feature))byFeature.set(feature,{feedback:[],studies:[study],external:[],competitors:[]})}
  for(const signal of context?.external||[]){if(signal.vehicle!==config.vehicle||signal.market!==config.market||!signal.feature)continue;if(!byFeature.has(signal.feature))byFeature.set(signal.feature,{feedback:[],studies:[],external:[],competitors:[]});byFeature.get(signal.feature).external.push(signal)}
  for(const signal of context?.competitors||[]){if(signal.vehicle!==config.vehicle||signal.market!==config.market||!signal.feature)continue;const feature=competitorFeatureMatch(signal.feature,[...byFeature.keys()]);if(!byFeature.has(feature))byFeature.set(feature,{feedback:[],studies:[],external:[],competitors:[]});byFeature.get(feature).competitors.push(signal)}
  const maxFrequency=Math.max(1,...[...byFeature.values()].map(bucket=>new Set(bucket.feedback.map(x=>x.feedbackId)).size));
  const requirements=[...byFeature].map(([feature,bucket])=>{
    const unique=[...new Map(bucket.feedback.map(item=>[item.feedbackId,item])).values()],studies=bucket.studies,external=bucket.external||[],competitors=bucket.competitors||[];
    const months=monthsFor(feature),peopleNeeded=Math.max(2,Math.ceil(months/3));
    const frequencyScore=Math.round(unique.length/maxFrequency*100),marketScore=Math.min(100,(studies.length?45+Math.min(20,studies.length*5):0)+Math.min(35,competitors.length*7)+Math.min(20,external.length*10)+(intelligence.sales?10:0));
    const fitScore=Math.round(Math.min(100,(config.months*Math.max(1,config.people)/(months*peopleNeeded))*70));
    const importance=Number(config.importance)/10,historicalBonus=config.historyFeatures?.includes(feature)?5:0;
    let score=Math.min(100,Math.round(frequencyScore*(.60-importance*.20)+fitScore*(.25+importance*.20)+marketScore*.15+historicalBonus));
    if(statuses[feature]==='deleted')score=-1;
    if(['not-feasible','pm-rejected'].includes(statuses[feature]))score=0;
    if(statuses[feature]==='conditional'||statuses[feature]==='approved-conditional')score-=12;
    const qualityCounts=unique.reduce((out,row)=>(out[row.quality]=(out[row.quality]||0)+1,out),{});
    const feedbackCitations=unique.slice(0,8).map(r=>({evidenceId:r.evidenceId,file:r.sourceFile,sheet:r.sheet,row:r.row,column:'Customer Feedback / Feature classification',excerpt:r.text,feedbackId:r.feedbackId,sourceType:'customer_feedback'}));
    const studyCitations=studies.slice(0,4).map(row=>({evidenceId:row.evidenceId,file:row.sourceFile,sheet:row.sheet,row:row.row,column:'Market study measure',excerpt:String(row.cells.A),feedbackId:row.evidenceId,sourceType:'market_study'}));
    const competitorCitations=competitors.map(signal=>({evidenceId:signal.evidenceId,file:signal.sourceFile,sheet:signal.sheet,row:signal.row,column:`Competitor signal · ${signal.classificationBasis}`,excerpt:signal.rationale,feedbackId:signal.evidenceId,sourceType:signal.sourceType||'competitor_intelligence',url:signal.sourceUrl||''}));
    const externalCitations=external.flatMap(signal=>signal.sourceUrls.slice(0,4).map(url=>({evidenceId:signal.evidenceId,file:url,sheet:'External web intelligence',row:'live',column:'Cited market signal',excerpt:signal.rationale,feedbackId:signal.evidenceId,sourceType:'external_web',url})));
    const salesCitation=intelligence.sales?{evidenceId:intelligence.sales.evidenceId,file:intelligence.sales.sourceFile,sheet:intelligence.sales.sheet,row:intelligence.sales.row,column:'2025 / 2030 sales volume',excerpt:`${intelligence.sales.marketName}: ${Number(intelligence.sales.volume2025).toLocaleString()} vehicles in 2025 and ${Number(intelligence.sales.volume2030).toLocaleString()} projected for 2030.`,feedbackId:intelligence.sales.evidenceId,sourceType:'sales_volume'}:null;
    const marketSummary=`${studies.length} relevant customer-study measure${studies.length===1?'':'s'}, ${competitors.length} row-traceable competitor signal${competitors.length===1?'':'s'}, and ${externalCitations.length} current cited web-market signal${externalCitations.length===1?'':'s'}${intelligence.sales?` plus ${intelligence.sales.marketName} sales planning (${Number(intelligence.sales.volume2025).toLocaleString()} in 2025; ${Number(intelligence.sales.volume2030).toLocaleString()} projected for 2030)`:''}`;
    return {
      id:`req-${feature.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'')}`,feature,group:groupFor(feature),outcome:outcomeFor(feature),
      statement:overrides[feature]||external[0]?.statement||requirementStatement(feature,bucket.feedback,!unique.length),problem:`Evidence identifies ${feature.toLowerCase()} as a product-cycle priority for ${config.vehicle} in ${config.market}.`,
      frequency:unique.length,evidenceCount:unique.length+studies.length+competitors.length+externalCitations.length+(salesCitation?1:0),marketEvidenceCount:studies.length+competitors.length+externalCitations.length+(salesCitation?1:0),score,scoreBreakdown:{frequency:frequencyScore,marketIntelligence:marketScore,timeToMarketFit:fitScore,deadlineImportance:Number(config.importance),historicalDecisionBonus:historicalBonus},
      estimatedMonths:months,estimatedPeople:peopleNeeded,fitScore,status:statuses[feature]||'not-checked',owner:entityFor(feature),
      confidence:unique.length+studies.length+competitors.length+externalCitations.length>=10?'high':unique.length+studies.length+competitors.length+externalCitations.length>=3?'medium':'low',evidenceQuality:qualityCounts,
      citations:[...feedbackCitations,...studyCitations,...competitorCitations,...externalCitations,...(salesCitation?[salesCitation]:[])],
      whyExists:`${unique.length} unique, relevant feedback record${unique.length===1?'':'s'} and ${marketSummary} support this requirement. Low-quality and duplicate feedback does not contribute to the count.`,
      rankBasis:`Feedback frequency: ${unique.length} (${frequencyScore}/100 normalized). Market intelligence: ${marketScore}/100. Planning estimate: ${months} months with about ${peopleNeeded} people. Against the PM’s ${config.months}-month target, ${config.people}-person team and ${config.importance}/10 deadline importance, time-to-market fit is ${fitScore}/100.${historicalBonus?` Relevant demo-cycle memory adds ${historicalBonus} points.`:''}`
    };
  }).filter(r=>r.citations.length&&r.score>=0);

  const groups=new Map();for(const requirement of requirements){if(!groups.has(requirement.group))groups.set(requirement.group,[]);groups.get(requirement.group).push(requirement)}
  return [...groups].map(([name,items])=>{
    const sorted=items.sort((a,b)=>b.score-a.score||b.frequency-a.frequency);
    const rejected=sorted.filter(item=>['not-feasible','pm-rejected'].includes(item.status));
    const active=sorted.filter(item=>!['not-feasible','pm-rejected'].includes(item.status));
    const selected=[...active.slice(0,Math.max(0,10-rejected.length)),...rejected.slice(0,10)].slice(0,10);
    const ranked=selected.map((r,index)=>{
      if(['not-feasible','pm-rejected'].includes(r.status))return {...r,rank:index+1,whyRanked:`This requirement remains visible for decision traceability after rejection. It no longer competes in the active priority ranking and has a score of 0/100. ${r.rankBasis}`};
      const above=index?` It ranks below “${selected[index-1].feature}” (${selected[index-1].score}) because its combined evidence and schedule score is lower.`:'';
      const below=index<selected.length-1?` It ranks above “${selected[index+1].feature}” (${selected[index+1].score}) because its combined score is higher.`:'';
      return {...r,rank:index+1,whyRanked:`${r.rankBasis} Final score: ${r.score}/100.${above}${below}`};
    });
    return {name,description:`BMW domain containing evidence-backed outcomes such as ${[...new Set(ranked.map(r=>r.outcome))].slice(0,4).join(', ')}. The PM can rename, split, or merge this group.`,evidenceSummary:`${ranked.reduce((sum,r)=>sum+r.evidenceCount,0)} cited feedback and market-intelligence links across ${ranked.length} ranked requirements.`,requirements:ranked};
  }).filter(g=>g.requirements.length).sort((a,b)=>b.requirements[0].score-a.requirements[0].score);
}

export function validateCitations(groups,evidence,context={}){const ids=new Set([...evidence,...(context.studies||[]),...(context.sales||[]),...(context.competitors||[]),...(context.external||[])].map(r=>r.evidenceId));return groups.flatMap(g=>g.requirements).every(r=>r.citations.length&&r.citations.every(c=>ids.has(c.evidenceId)))}

async function loadDecisionEvents(){
  try{const response=await fetch('/api/decision-events'),payload=await readApiResponse(response);const known=new Set(state.events.map(event=>event.id));state.events.push(...payload.events.filter(event=>isRecordedDecision(event)&&!known.has(event.id)))}catch{}
}

function addEvent(type, title, description, data={},actor='PM') {
  if(!DECISION_EVENT_TYPES.has(type)||!String(data.rationale||'').trim())return;
  const event={ id: crypto.randomUUID(), type, title, description, data, actor, at: new Date().toISOString(), provenance:'Append-only application event' };
  state.events.unshift(event);
  localStorage.setItem('decision-events', JSON.stringify(state.events));
  fetch('/api/decision-events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(event)}).catch(()=>{});
  renderMemory();
}

function groundingEvidence(requirement){
  const feedback=requirement.citations.filter(citation=>citation.sourceType==='customer_feedback').slice(0,3),market=requirement.citations.filter(citation=>citation.sourceType!=='customer_feedback').slice(0,3),selected=[...feedback,...market];
  for(const citation of requirement.citations){if(selected.length>=6)break;if(!selected.includes(citation))selected.push(citation)}
  return selected.map(citation=>({evidence_id:citation.evidenceId,source_type:citation.sourceType,excerpt:String(citation.excerpt||'').slice(0,280)}));
}

async function synthesizeGroundedWording(groups){
  if(!state.openAIConfigured)return 0;
  const overrides=overrideMap(),requirements=groups.flatMap(group=>group.requirements.filter(requirement=>!overrides[requirement.feature]&&requirement.wordingSource!=='openai-grounded').map(requirement=>({id:requirement.id,feature:requirement.feature,group:group.name,outcome:requirement.outcome,fallback_statement:requirement.statement,evidence:groundingEvidence(requirement)}))).filter(requirement=>requirement.evidence.length);
  if(!requirements.length)return 0;
  const response=await fetch('/api/synthesize-requirements',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productContext:state.config,requirements})}),result=await readApiResponse(response),byId=new Map(result.requirements.map(requirement=>[requirement.requirementId,requirement]));
